import{_ as l,a0 as p,w as o,s as r,ao as h,I as n,x as t,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"awk 系列：如何使用 awk 和正則表達式過濾文本或文件中的字符串 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 和正則表達式過濾文本或文件中的字符串 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 和正則表達式過濾文本或文件中的字符串 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 和正則表達式過濾文本或文件中的字符串 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 1 - How to Use Awk and Regular Expressions to Filter Text or String in Files","title":"awk 系列：如何使用 awk 和正則表達式過濾文本或文件中的字符串","tag":"awk","desc":""},"relativePath":"awk/Part 1 - How to Use Awk and Regular Expressions to Filter Text or String in Files.md","filePath":"[post].md"}'),c={name:"awk/Part 1 - How to Use Awk and Regular Expressions to Filter Text or String in Files.md"};function d(k,a,g,w,u,b){const s=p("Link");return o(),r("div",null,[a[13]||(a[13]=h(`<h1 id="awk-系列-如何使用-awk-和正則表達式過濾文本或文件中的字符串" tabindex="-1">awk 系列：如何使用 awk 和正則表達式過濾文本或文件中的字符串 <a class="header-anchor" href="#awk-系列-如何使用-awk-和正則表達式過濾文本或文件中的字符串" aria-label="Permalink to “awk 系列：如何使用 awk 和正則表達式過濾文本或文件中的字符串”">​</a></h1><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Linux-Awk-Command-Examples.png" alt=""></p><p>當我們在 Unix/Linux 下使用特定的命令從字符串或文件中讀取或編輯文本時，我們經常需要過濾輸出以得到感興趣的部分。這時正則表達式就派上用場了。</p><h3 id="什麼是正則表達式" tabindex="-1">什麼是正則表達式? <a class="header-anchor" href="#什麼是正則表達式" aria-label="Permalink to “什麼是正則表達式?”">​</a></h3><p>正則表達式可以定義為代表若干個字符序列的字符串。它最重要的功能之一就是它允許你過濾一條命令或一個文件的輸出、編輯文本或配置文件的一部分等等。</p><h3 id="正則表達式的特點" tabindex="-1">正則表達式的特點 <a class="header-anchor" href="#正則表達式的特點" aria-label="Permalink to “正則表達式的特點”">​</a></h3><p>正則表達式由以下內容組合而成：</p><ul><li><strong>普通字符</strong>，例如空格、下劃線、A-Z、a-z、0-9。</li><li>可以擴展為普通字符的<strong>元字符</strong>，它們包括： <ul><li><code>(.)</code> 它匹配除了換行符外的任何單個字符。</li><li><code>(*)</code> 它匹配零個或多個在其之前緊挨着的字符。</li><li><code>[ character(s) ]</code> 它匹配任何由其中的字符/字符集指定的字符，你可以使用連字符(-)代表字符區間，例如 [a-f]、[1-5]等。</li><li><code>^</code> 它匹配文件中一行的開頭。</li><li><code>$</code> 它匹配文件中一行的結尾。</li><li><code>\\</code> 這是一個轉義字符。</li></ul></li></ul><p>你必須使用類似 awk 這樣的文本過濾工具來過濾文本。你還可以把 awk 自身當作一個編程語言。但由於這個指南的適用範圍是關於使用 awk 的，我會按照一個簡單的命令列過濾工具來介紹它。</p><p>awk 的一般語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;script&#39; filename</span></span></code></pre></div><p>此處 <code>&#39;script&#39;</code> 是一個由 awk 可以理解並應用於 filename 的命令集合。</p><p>它通過讀取文件中的給定行，複製該行的內容並在該行上執行腳本的方式工作。這個過程會在該文件中的所有行上重複。</p><p>該腳本 <code>&#39;script&#39;</code> 中內容的格式是 <code>&#39;/pattern/ action&#39;</code>，其中 <code>pattern</code> 是一個正則表達式，而 <code>action</code> 是當 awk 在該行中找到此模式時應當執行的動作。</p><h3 id="如何在-linux-中使用-awk-過濾工具" tabindex="-1">如何在 Linux 中使用 awk 過濾工具 <a class="header-anchor" href="#如何在-linux-中使用-awk-過濾工具" aria-label="Permalink to “如何在 Linux 中使用 awk 過濾工具”">​</a></h3><p>在下面的例子中，我們將聚焦於之前討論過的元字符。</p><h4 id="一個使用-awk-的簡單示例" tabindex="-1">一個使用 awk 的簡單示例： <a class="header-anchor" href="#一個使用-awk-的簡單示例" aria-label="Permalink to “一個使用 awk 的簡單示例：”">​</a></h4><p>下面的例子打印文件 /etc/hosts 中的所有行，因為沒有指定任何的模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;//{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Awk-Command-Example.gif" alt=""></p><p><em>awk 打印文件中的所有行</em></p><h4 id="結合模式使用-awk" tabindex="-1">結合模式使用 awk <a class="header-anchor" href="#結合模式使用-awk" aria-label="Permalink to “結合模式使用 awk”">​</a></h4><p>在下面的示例中，指定了模式 <code>localhost</code>，因此 awk 將匹配文件 <code>/etc/hosts</code> 中有 <code>localhost</code> 的那些行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/localhost/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-Command-with-Pattern.gif" alt=""></p><p><em>awk 打印文件中匹配模式的行</em></p><h4 id="在-awk-模式中使用通配符" tabindex="-1">在 awk 模式中使用通配符 (.) <a class="header-anchor" href="#在-awk-模式中使用通配符" aria-label="Permalink to “在 awk 模式中使用通配符 (.)”">​</a></h4><p>在下面的例子中，符號 <code>(.)</code> 將匹配包含 loc、localhost、localnet 的字符串。</p><p>這裏的正則表達式的意思是匹配 <strong>l一個字符c</strong>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/l.c/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-with-Wild-Cards.gif" alt=""></p><p><em>使用 awk 打印文件中匹配模式的字符串</em></p><h4 id="在-awk-模式中使用字符" tabindex="-1">在 awk 模式中使用字符 (*) <a class="header-anchor" href="#在-awk-模式中使用字符" aria-label="Permalink to “在 awk 模式中使用字符 (*)”">​</a></h4><p>在下面的例子中，將匹配包含 localhost、localnet、lines, capable 的字符串。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/l*c/{print}&#39; /etc/localhost</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Match-Strings-in-File.gif" alt=""></p><p><em>使用 awk 匹配文件中的字符串</em></p><p>你可能也意識到 <code>(*)</code> 將會嘗試匹配它可能檢測到的最長的匹配。</p><p>讓我們看一看可以證明這一點的例子，正則表達式 <code>t*t</code> 的意思是在下面的行中匹配以 <code>t</code> 開始和 <code>t</code> 結束的字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>this is tecmint, where you get the best good tutorials, how to&#39;s, guides, tecmint.</span></span></code></pre></div><p>當你使用模式 <code>/t*t/</code> 時，會得到如下可能的結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>this is t</span></span>
<span class="line"><span>this is tecmint</span></span>
<span class="line"><span>this is tecmint, where you get t</span></span>
<span class="line"><span>this is tecmint, where you get the best good t</span></span>
<span class="line"><span>this is tecmint, where you get the best good tutorials, how t</span></span>
<span class="line"><span>this is tecmint, where you get the best good tutorials, how tos, guides, t</span></span>
<span class="line"><span>this is tecmint, where you get the best good tutorials, how tos, guides, tecmint</span></span></code></pre></div><p>在 <code>/t*t/</code> 中的通配符 <code>(*)</code> 將使得 awk 選擇匹配的最後一項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>this is tecmint, where you get the best good tutorials, how to&#39;s, guides, tecmint</span></span></code></pre></div><h4 id="結合集合-character-s-使用-awk" tabindex="-1">結合集合 [ character(s) ] 使用 awk <a class="header-anchor" href="#結合集合-character-s-使用-awk" aria-label="Permalink to “結合集合 [ character(s) ] 使用 awk”">​</a></h4><p>以集合 [al1] 為例，awk 將匹配文件 /etc/hosts 中所有包含字符 a 或 l 或 1 的字符串。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/[al1]/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Print-Matching-Character.gif" alt=""></p><p><em>使用 awk 打印文件中匹配的字符</em></p><p>下一個例子匹配以 <code>K</code> 或 <code>k</code> 開始頭，後面跟着一個 <code>T</code> 的字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/[Kk]T/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Print-Matched-String-in-File.gif" alt=""></p><p><em>使用 awk 打印文件中匹配的字符</em></p><h4 id="以範圍的方式指定字符" tabindex="-1">以範圍的方式指定字符 <a class="header-anchor" href="#以範圍的方式指定字符" aria-label="Permalink to “以範圍的方式指定字符”">​</a></h4><p>awk 所能理解的字符：</p><ul><li><code>[0-9]</code> 代表一個單獨的數字</li><li><code>[a-z]</code> 代表一個單獨的小寫字母</li><li><code>[A-Z]</code> 代表一個單獨的大寫字母</li><li><code>[a-zA-Z]</code> 代表一個單獨的字母</li><li><code>[a-zA-Z 0-9]</code> 代表一個單獨的字母或數字</li></ul><p>讓我們看看下面的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/[0-9]/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-To-Print-Matching-Numbers-in-File.gif" alt=""></p><p><em>使用 awk 打印文件中匹配的數字</em></p><p>在上面的例子中，文件 /etc/hosts 中的所有行都至少包含一個單獨的數字 [0-9]。</p><h4 id="結合元字符-使用-awk" tabindex="-1">結合元字符 (^) 使用 awk <a class="header-anchor" href="#結合元字符-使用-awk" aria-label="Permalink to “結合元字符 (^) 使用 awk”">​</a></h4><p>在下面的例子中，它匹配所有以給定模式開頭的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/^fe/{print}&#39; /etc/hosts</span></span>
<span class="line"><span># awk &#39;/^ff/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Print-All-Matching-Lines-with-Pattern.gif" alt=""></p><p><em>使用 awk 打印與模式匹配的行</em></p><h4 id="結合元字符-使用-awk-1" tabindex="-1">結合元字符 ($) 使用 awk <a class="header-anchor" href="#結合元字符-使用-awk-1" aria-label="Permalink to “結合元字符 ($) 使用 awk”">​</a></h4><p>它將匹配所有以給定模式結尾的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;/ab$/{print}&#39; /etc/hosts</span></span>
<span class="line"><span># awk &#39;/ost$/{print}&#39; /etc/hosts</span></span>
<span class="line"><span># awk &#39;/rs$/{print}&#39; /etc/hosts</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Print-Given-Pattern-String.gif" alt=""></p><p><em>使用 awk 打印與模式匹配的字符串</em></p><h4 id="結合轉義字符-使用-awk" tabindex="-1">結合轉義字符 (\\) 使用 awk <a class="header-anchor" href="#結合轉義字符-使用-awk" aria-label="Permalink to “結合轉義字符 (\\) 使用 awk”">​</a></h4><p>它允許你將該轉義字符後面的字符作為文字，即理解為其字面的意思。</p><p>在下面的例子中，第一個命令打印出文件中的所有行，第二個命令中我想匹配具有 $25.00 的一行，但我並未使用轉義字符，因而沒有打印出任何內容。</p><p>第三個命令是正確的，因為一個這裏使用了一個轉義字符以轉義 $，以將其識別為 &#39;$&#39;（而非元字符）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;//{print}&#39; deals.txt</span></span>
<span class="line"><span># awk &#39;/$25.00/{print}&#39; deals.txt</span></span>
<span class="line"><span># awk &#39;/\\$25.00/{print}&#39; deals.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-with-Escape-Character.gif" alt=""></p><p><em>結合轉義字符使用 awk</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>以上內容並不是 awk 命令用做過濾工具的全部，上述的示例均是 awk 的基礎操作。在下面的章節中，我將進一步介紹如何使用 awk 的高級功能。感謝您的閲讀，請在評論區貼出您的評論。</p><hr>`,81)),n("p",null,[a[1]||(a[1]=t("via: ",-1)),e(s,{href:"http://www.tecmint.com/use-linux-awk-command-to-filter-text-string-in-files/"},{default:i(()=>[...a[0]||(a[0]=[t("http://www.tecmint.com/use-linux-awk-command-to-filter-text-string-in-files/",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=t("作者：",-1)),e(s,{href:"http://www.tecmint.com/author/aaronkili/"},{default:i(()=>[...a[2]||(a[2]=[t("Aaron Kili",-1)])]),_:1}),a[6]||(a[6]=t(" 譯者：",-1)),e(s,{href:"https://github.com/wwy-hust"},{default:i(()=>[...a[3]||(a[3]=[t("wwy-hust",-1)])]),_:1}),a[7]||(a[7]=t(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=t("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[t("LCTT",-1)])]),_:1}),a[11]||(a[11]=t(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[t("Linux中國",-1)])]),_:1}),a[12]||(a[12]=t(" 榮譽推出",-1))])])}const y=l(c,[["render",d]]);export{x as __pageData,y as default};
